players.script:
# turtle.pf — patient defender.
# Strategy: block while the enemy attacks and kick back as soon as it is in
# kick range and not attacking, with a sweep before a 6th kick in a row
# would go stale. Blocking forever is not safe: the 4th block
# in a row breaks the guard, so after 3 blocks it backs off instead. A
# blocked kick is answered with a throw, since a throw beats a block.
loop {
  if enemy.attacking {
    if guard >= 3 { move_back x3 } else { high_block hold 6 }
  } elif in_range(kick) {
    if repeats >= 5 { sweep } else { kick }
  } else {
    high_block hold 8
  }
}
on_block { throw }
on_hit { move_back x3 }

# jumper.pf — air assault.
# Strategy: walk in, then jump forward and kick late in the jump. A kick
# started on airborne frames 17-20 is a landing low: it carries through
# touchdown, hits ducking fighters and goes under a high_block, so it must be
# blocked low. It loses to fighters who poke it out of the air with quick
# grounded attacks: any hit on an airborne fighter knocks it down.
loop {
  if distance > 24 {
    move_forward x5
  } else {
    jump_forward
    wait 15
    kick
  }
}
on_hit { move_back x2 }
